mapper.select:
SELECT 
FROM message_recipient
INNER JOIN message_notice ON message_notice.tenant_id = #{tenantId}
    AND message_notice.id = message_recipient.message_id
    AND message_notice.del_flag = '0'
    AND message_notice.status = 'PUBLISHED'
WHERE message_recipient.tenant_id = #{tenantId}
  AND message_recipient.recipient_type = #{recipientType}
  AND message_recipient.recipient_id = #{recipientId}
  AND message_recipient.inbox_status = 'VISIBLE'
  AND message_recipient.del_flag = '0'
  AND (message_notice.expire_time IS NULL OR message_notice.expire_time > NOW())

    AND message_recipient.id < #{cursor}

ORDER BY message_recipient.id DESC
LIMIT #{fetchSize}

SELECT 
FROM message_recipient
INNER JOIN message_notice ON message_notice.tenant_id = #{tenantId}
    AND message_notice.id = message_recipient.message_id
    AND message_notice.del_flag = '0'
WHERE message_recipient.tenant_id = #{tenantId}
  AND message_recipient.recipient_type = #{recipientType}
  AND message_recipient.recipient_id = #{recipientId}
  AND message_recipient.message_id = #{messageId}
  AND message_recipient.del_flag = '0'

SELECT COUNT(1)
FROM message_recipient
INNER JOIN message_notice ON message_notice.tenant_id = #{tenantId}
    AND message_notice.id = message_recipient.message_id
    AND message_notice.status = 'PUBLISHED'
    AND message_notice.del_flag = '0'
WHERE message_recipient.tenant_id = #{tenantId}
  AND message_recipient.recipient_type = #{recipientType}
  AND message_recipient.recipient_id = #{recipientId}
  AND message_recipient.read_status = '0'
  AND message_recipient.inbox_status = 'VISIBLE'
  AND message_recipient.del_flag = '0'
  AND (message_notice.expire_time IS NULL OR message_notice.expire_time > NOW())

mapper.update:
UPDATE message_recipient
SET read_status = '1', read_time = COALESCE(read_time, NOW()), update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND message_id = #{messageId}
  AND del_flag = '0'

UPDATE message_recipient
SET read_status = '1', read_time = COALESCE(read_time, NOW()), update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND read_status = '0'
  AND del_flag = '0'

UPDATE message_recipient
SET inbox_status = 'HIDDEN', update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND message_id = #{messageId}
  AND del_flag = '0'

